import { cp, readdir } from "node:fs/promises";
import { basename, extname, join } from "node:path";
import { type ConfigPlugin, withDangerousMod } from "expo/config-plugins";

/**
 * Copies every `.symbolset` bundle into the app's asset catalog so
 * `Image assetName` can name it.
 *
 * There is no Expo option for custom symbols, and `ios/` is generated rather
 * than committed, so a symbol added by hand in Xcode would not survive the next
 * prebuild. Generated by `scripts/generate-symbolsets.ts`, which is where the
 * template geometry lives.
 *
 * Only the copy is needed: `actool` compiles whatever it finds in
 * `Images.xcassets`, so nothing has to be registered in the pbxproj — unlike an
 * alternate app icon, which also needs build settings (`with-alternate-icons`).
 */
const withSymbolsets: ConfigPlugin<{ directory: string }> = (
	config,
	{ directory },
) =>
	withDangerousMod(config, [
		"ios",
		async (dangerousConfig) => {
			const { platformProjectRoot, projectName, projectRoot } =
				dangerousConfig.modRequest;
			if (!projectName) {
				throw new Error("withSymbolsets: no iOS project name.");
			}

			const source = join(projectRoot, directory);
			const catalog = join(platformProjectRoot, projectName, "Images.xcassets");

			const entries = await readdir(source, { withFileTypes: true });
			const bundles = entries.filter(
				(entry) => entry.isDirectory() && extname(entry.name) === ".symbolset",
			);

			if (bundles.length === 0) {
				throw new Error(
					`withSymbolsets: no .symbolset bundles in ${directory} — run \`pnpm gen:symbolsets\`.`,
				);
			}

			for (const bundle of bundles) {
				await cp(join(source, bundle.name), join(catalog, bundle.name), {
					recursive: true,
				});
			}

			return dangerousConfig;
		},
	]);

export default withSymbolsets;

/** The names this plugin makes available to `Image assetName`. */
export const symbolName = (bundle: string) => basename(bundle, ".symbolset");
